 const normal=REAL_HTTP['normal-2'];if(normal)await run('真实完整proof截断/错身份/数组/流水/余额均保留unknown',async()=>{const mutations=[p=>p.current_actor_id++,p=>delete p.assembly_completion_receipt.output_movement_id,p=>p.assembly_completion_receipt.request.jobs.reverse(),p=>p.assembly_completion_receipt.members[0].remaining_stock_quantity++,p=>p.assembly_completion_receipt.inputs[0].movement_key='bad',p=>p.assembly_completion_receipt.extra='unapproved'];for(const mutate of mutations){cache.map.clear();posts.length=0;const c=await prepareActual(normal),data=JSON.parse(JSON.stringify(normal.write.body));mutate(data);reply=data;await sendActual(c,normal);assert.equal(c.stockAssembleRows[0].state,'unknown');assert.equal(c.stockAssembleStore().list().length,1);assert.ok(c.stockPrepDialog)}});
 if(normal)await run('真实成功与列表/清缓存/trace失败分开保留，GET-only再刷新',async()=>{const c=await prepareActual(normal);reply=normal.write.body;getError=Error('GET failed');const remove=cache.removeItem;cache.removeItem=()=>{throw Error('storage locked')};await sendActual(c,normal);const rec=c.stockAssembleRows[0];assert.equal(rec.state,'confirmed');assert.ok(rec.cacheError&&rec.refreshError);assert.equal(c.stockAssembleStore().list().length,1);cache.removeItem=remove;getError=null;await c.refreshStockAssembleList(rec);assert.equal(rec.refreshError,'');getError=Error('history denied');await c.viewStockAssembleTrace(rec);assert.equal(rec.state,'confirmed');assert.ok(rec.lastError.includes('读取失败'));assert.equal(posts.length,1);getError=null;await open(c,row('different-group'));c.stockOperationKey=()=> 'independent-B-key';reply=null;await assemble(c);assert.equal(posts.length,2)});
